// Checks the Shopify signature, then turns the order into the values this workflow writes.
// The Crypto node above computed the expected signature from the raw body with SHOPIFY_WEBHOOK_SECRET.
// Verdicts: accepted, ignored (another topic), invalid (signed but not an order), unauthorized, error.
const hook = $('Webhook: Shopify Orders').item.json;
const headers = hook.headers || {};
const secret = String($env.SHOPIFY_WEBHOOK_SECRET || '');
const topic = String(headers['x-shopify-topic'] || '').trim();
const TOPICS = ['orders/create', 'orders/updated'];
const out = {
  verdict: 'accepted', reason: '', topic,
  webhookId: String(headers['x-shopify-webhook-id'] || '').trim(),
  eventId: String(headers['x-shopify-event-id'] || '').trim(),
  receivedAt: new Date().toISOString(),
};

// Headers are not covered by the signature, and these reasons end up in a Slack alert. Show header values with
// safe characters only, so a forged call cannot post <!channel> or a link through the error workflow.
const shown = (v) => (String(v || '').replace(/[^A-Za-z0-9._\/@-]/g, '?').slice(0, 64) || 'none');

// Compare without stopping at the first different character.
function sameSignature(a, b) {
  if (!a || !b || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const num = (v) => { const n = Number.parseFloat(v); return Number.isFinite(n) ? n : 0; };
const money = (v) => Math.round(num(v) * 100) / 100;
const int = (v) => { const n = Number.parseInt(v, 10); return Number.isFinite(n) ? n : 0; };
const text = (v) => (v === null || v === undefined ? '' : String(v).trim());
const isoTime = (v) => { if (!v) return null; const t = Date.parse(v); return Number.isNaN(t) ? null : new Date(t).toISOString(); };

const FINANCIAL = {
  pending: 'Pending', authorized: 'Authorized', partially_paid: 'Partially Paid', paid: 'Paid',
  partially_refunded: 'Partially Refunded', refunded: 'Refunded', voided: 'Voided', expired: 'Expired',
};
const FULFILLMENT = {
  fulfilled: 'Fulfilled', partial: 'Partial', restocked: 'Restocked', not_eligible: 'Not Eligible', unfulfilled: 'Unfulfilled',
};

try {
  if (!secret) {
    return { json: { ...out, verdict: 'error', reason: 'SHOPIFY_WEBHOOK_SECRET is not set, so no Shopify webhook can be trusted' } };
  }
  const given = String(headers['x-shopify-hmac-sha256'] || '').trim();
  if (!sameSignature(String($json.expectedHmac || ''), given)) {
    return { json: { ...out, verdict: 'unauthorized',
      reason: `Rejected a Shopify webhook with a ${given ? 'wrong' : 'missing'} X-Shopify-Hmac-Sha256 signature (topic ${shown(topic)}, webhook id ${shown(out.webhookId)})` } };
  }
  if (!TOPICS.includes(topic)) {
    return { json: { ...out, verdict: 'ignored', reason: `Topic ${shown(topic)} is not handled here` } };
  }
  const o = hook.body;
  if (!o || typeof o !== 'object' || !o.id || !Array.isArray(o.line_items) || o.line_items.length === 0
      || o.line_items.some((li) => !li || !li.id)) {
    return { json: { ...out, verdict: 'invalid', reason: `A signed ${shown(topic)} webhook (id ${shown(out.webhookId)}) did not contain an order with line items` } };
  }
  if (!out.webhookId) out.webhookId = `no-webhook-id-${o.id}-${text(o.updated_at)}-${topic}`;

  // Refunds: units per line, and the money actually refunded.
  const refundedQty = {};
  let refundTotal = 0;
  for (const r of o.refunds || []) {
    for (const rli of r.refund_line_items || []) {
      const key = text(rli.line_item_id);
      refundedQty[key] = (refundedQty[key] || 0) + int(rli.quantity);
    }
    const tx = (r.transactions || []).filter((t) => t && t.kind === 'refund' && t.status === 'success');
    if (tx.length) refundTotal += tx.reduce((s, t) => s + num(t.amount), 0);
    else refundTotal += (r.refund_line_items || []).reduce((s, x) => s + num(x.subtotal) + num(x.total_tax), 0);
  }

  const lines = o.line_items.map((li, i) => {
    const id = text(li.id);
    const quantity = int(li.quantity);
    const refunded = refundedQty[id] || 0;
    const current = li.current_quantity === null || li.current_quantity === undefined
      ? Math.max(quantity - refunded, 0) : int(li.current_quantity);
    const unit = money(li.price);
    const skuRaw = li.sku === null || li.sku === undefined ? '' : String(li.sku);
    return {
      id, position: i + 1, skuRaw, sku: skuRaw.trim().toUpperCase(), title: text(li.title || li.name),
      variantId: li.variant_id ? String(li.variant_id) : '', quantity, current, refunded, unit,
      total: Math.round(unit * current * 100) / 100,
    };
  });

  // Gift orders: a cart attribute such as "Gift" = "Yes" or "Gift Message" = "...", or the tag "gift".
  const attrs = (o.note_attributes || []).map((a) => ({ name: text(a && a.name).toLowerCase(), value: text(a && a.value) }));
  const tags = text(o.tags).split(',').map((t) => t.trim()).filter(Boolean);
  const giftMessage = (attrs.find((a) => a.name.includes('gift') && /(message|note)/.test(a.name) && a.value) || {}).value || '';
  const giftFlag = attrs.some((a) => a.name.includes('gift') && !/(message|note)/.test(a.name) && /^(yes|y|true|1|on)$/i.test(a.value));
  const isGift = Boolean(giftMessage) || giftFlag || tags.some((t) => t.toLowerCase() === 'gift');

  const s = o.shipping_address && typeof o.shipping_address === 'object' ? o.shipping_address : null;
  const ship = s ? {
    name: text(s.name) || [text(s.first_name), text(s.last_name)].filter(Boolean).join(' '),
    address: [text(s.address1), text(s.address2)].filter(Boolean).join(', '),
    city: text(s.city), region: text(s.province_code), country: text(s.country_code).toUpperCase(), zip: text(s.zip),
  } : null;

  const c = o.customer && typeof o.customer === 'object' ? o.customer : {};
  const email = text(o.email || o.contact_email || c.email).toLowerCase();
  const consent = c.email_marketing_consent && c.email_marketing_consent.state;
  const customer = {
    shopifyId: c.id ? String(c.id) : '',
    email,
    name: [text(c.first_name), text(c.last_name)].filter(Boolean).join(' ') || (ship ? ship.name : ''),
    phone: text(c.phone || o.phone || (s && s.phone)),
    acceptsMarketing: consent ? consent === 'subscribed' : Boolean(o.buyer_accepts_marketing),
  };

  const shippingSet = o.total_shipping_price_set && o.total_shipping_price_set.shop_money;
  const financialRaw = text(o.financial_status).toLowerCase();
  const fulfillmentRaw = text(o.fulfillment_status).toLowerCase();
  const cancelledAt = isoTime(o.cancelled_at);
  const closedAt = isoTime(o.closed_at);
  out.order = {
    shopifyId: String(o.id),
    number: text(o.name) || `#${text(o.order_number)}`,
    email,
    createdAt: isoTime(o.created_at),
    updatedAt: isoTime(o.updated_at) || isoTime(o.created_at),
    cancelledAt,
    financialRaw,
    financial: FINANCIAL[financialRaw] || null,
    fulfillmentRaw,
    fulfillment: fulfillmentRaw ? (FULFILLMENT[fulfillmentRaw] || null) : 'Unfulfilled',
    status: cancelledAt ? 'Cancelled' : (closedAt ? 'Closed' : 'Open'),
    subtotal: money(o.subtotal_price),
    shipping: money(shippingSet ? shippingSet.amount : (o.shipping_lines || []).reduce((t, l) => t + num(l.price), 0)),
    tax: money(o.total_tax),
    total: money(o.total_price),
    refunded: Math.round(refundTotal * 100) / 100,
    currency: text(o.currency) || 'USD',
    ship,
    tags: tags.join(', '),
    isGift,
    giftNote: isGift ? (giftMessage || text(o.note)) : '',
    customer,
    lines,
  };
  return { json: out };
} catch (e) {
  return { json: { ...out, verdict: 'error', reason: `Could not read the Shopify webhook (${String(e.message || e).replace(/: /g, ', ')})` } };
}

// Starts (or, after an Airtable cooldown, restarts) the work for one webhook.
// ctx.memo keeps what this webhook already decided or sent, so a restart only repeats the
// Airtable lookups and upserts (all safe to repeat) and never sends a Slack alert twice.
//
// Pacing: Airtable allows 5 requests per second per base, shared by everything that uses the base.
// Every Airtable call in this workflow waits 500 ms after the previous one, so one run makes at most
// 2 calls in any second, and two webhooks processed at the same moment stay at 4.
const ctx = { ...$json };
for (const k of ['error', 'failure', 'retry', 'records', 'repeat', 'stale', 'stored', 'alerts', 'cooldownSeconds']) delete ctx[k];
ctx.attempt = (ctx.attempt || 0) + 1;
ctx.memo = ctx.memo || {};
ctx.ids = { customer: null, order: null, products: {} };
ctx.counts = { linesCreated: 0, linesUpdated: 0 };
ctx.startedAt = ctx.startedAt || ctx.receivedAt || new Date().toISOString();
const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
ctx.q = { webhook: `{Event ID} = '${esc(ctx.webhookId)}'` };
ctx.step = 'Find Webhook';
return { json: ctx };

// Shopify can deliver the same webhook more than once. A delivery whose X-Shopify-Webhook-Id is already
// in Webhook Log as Processed or Ignored is skipped. A Failed row does not count, so a redelivery can heal it.
const ctx = { ...$('Code: Start Processing').item.json };
const rows = Array.isArray($json.records) ? $json.records : [];
const done = rows.find((r) => ['Processed', 'Ignored'].includes((r.fields || {}).Status));
// After a cooldown restart this run may have written that row itself, so it is not a repeat then.
ctx.repeat = Boolean(done) && !ctx.memo.webhookLogged;
if (!ctx.repeat) {
  const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  ctx.q.order = `{Shopify Order ID} = '${esc(ctx.order.shopifyId)}'`;
  ctx.step = 'Find Order';
  await new Promise((resolve) => setTimeout(resolve, 500)); // pace Airtable, see the note in Code: Start Processing
}
return { json: ctx };

// Looks at the order as Airtable has it now.
//  * stale: Shopify does not promise delivery order, so a webhook older than the stored Shopify Updated At is
//    ignored. This is checked again on every attempt: during a 31 to 60 second cooldown another webhook for the
//    same order can save a newer version, and the restarted run must not write the older one over it.
//  * melt check: run it for a new order, a changed shipping address, or when the last check ended in Review.
//    This is decided once per webhook (a cooldown restart keeps it, so the weather is never checked twice).
const ctx = { ...$('Code: Check Repeat').item.json };
const memo = ctx.memo;
const o = ctx.order;
const rows = Array.isArray($json.records) ? $json.records : [];

const limitEnv = Number.parseFloat($env.MELT_TEMP_C);
const daysEnv = Number.parseInt($env.MELT_FORECAST_DAYS, 10);
ctx.meltConfig = {
  limit: Number.isFinite(limitEnv) ? limitEnv : 27,
  days: Number.isFinite(daysEnv) ? Math.min(Math.max(daysEnv, 1), 16) : 3,
};

const key = (city, region, country) => [city, region, country].map((x) => String(x || '').trim().toLowerCase()).join('|');

// What Airtable holds right now (fresh on every attempt).
const now = rows[0] || null;
const nf = now ? now.fields || {} : {};
ctx.stored = now ? { id: now.id, updatedAt: nf['Shopify Updated At'] || null } : null;
memo.duplicateOrderRows = rows.length > 1;
ctx.stale = Boolean(ctx.stored && ctx.stored.updatedAt && o.updatedAt
  && Date.parse(o.updatedAt) < Date.parse(ctx.stored.updatedAt));

if (!memo.decided) {
  memo.before = now ? {
    id: now.id,
    updatedAt: nf['Shopify Updated At'] || null,
    coldPack: nf['Cold Pack'] || null,
    location: key(nf['Shipping City'], nf['Shipping Region'], nf['Shipping Country']),
    needsReview: Boolean(nf['Needs Review']),
    reviewReason: nf['Review Reason'] || '',
  } : null;

  const before = memo.before;
  let plan;
  if (o.status === 'Cancelled') plan = { run: false, note: 'Order cancelled, no melt check.' };
  else if (o.fulfillment === 'Fulfilled') plan = { run: false, note: 'Order already fulfilled, no melt check.' };
  else if (!o.ship || !o.ship.city) plan = { run: false, coldPack: 'Not Needed', note: 'No shipping address (pickup or digital order), no melt check.' };
  else if (!before) plan = { run: true, why: 'new order' };
  else if (before.location !== key(o.ship.city, o.ship.region, o.ship.country)) plan = { run: true, why: 'shipping address changed' };
  else if (!before.coldPack || before.coldPack === 'Review') plan = { run: true, why: before.coldPack ? 'the last check needs review' : 'not checked yet' };
  else plan = { run: false };
  memo.meltPlan = plan;
  // A new order that needs no check still gets a note (and Not Needed when there is no address to ship to).
  if (!plan.run && !before && plan.note) memo.melt = { coldPack: plan.coldPack || null, max: null, note: plan.note, checked: false };
  memo.decided = true;
}

ctx.meltNeeded = Boolean(!ctx.stale && memo.meltPlan && memo.meltPlan.run && !memo.melt);
if (ctx.meltNeeded) {
  const city = o.ship.city.replace(/,/g, ' ').trim();
  // count 10: the comma qualifier narrows the results, and asking for more than one keeps a qualified match
  // from being cut off. The first result (Open-Meteo orders them by relevance and population) is used.
  const query = { name: o.ship.region ? `${city}, ${o.ship.region}` : city, count: 10, language: 'en', format: 'json' };
  if (/^[A-Z]{2}$/.test(o.ship.country)) query.countryCode = o.ship.country;
  ctx.geo = { query, label: [o.ship.city, o.ship.region, o.ship.country].filter(Boolean).join(', ') };
}

const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
const c = o.customer;
const clauses = [];
if (c.shopifyId) clauses.push(`{Shopify Customer ID} = '${esc(c.shopifyId)}'`);
if (c.email) clauses.push(`LOWER(TRIM({Email})) = '${esc(c.email)}'`);
ctx.q.customer = clauses.length ? `OR(${clauses.join(', ')})` : 'FALSE()';
ctx.step = 'Find Customer';
await new Promise((resolve) => setTimeout(resolve, 500)); // pace Airtable
return { json: ctx };

// Customers are matched by lookup, never by an upsert on Email (Airtable does not take email fields as an
// upsert key, and the base has the same email on more than one record). Order of preference:
//   1. a record with this Shopify Customer ID, 2. a record whose LOWER(TRIM(Email)) matches,
//   and among several: Active before Duplicate, then one that has a Shopify Customer ID, then the oldest.
// A Duplicate record that points to its survivor in Merged Into is replaced by the survivor.
const ctx = { ...$('Code: Check Order').item.json };
const memo = ctx.memo;
const c = ctx.order.customer;
const recs = Array.isArray($json.records) ? $json.records : [];
const norm = (s) => String(s || '').trim().toLowerCase();

const byId = c.shopifyId ? recs.filter((r) => String((r.fields || {})['Shopify Customer ID'] || '').trim() === c.shopifyId) : [];
const byEmail = c.email ? recs.filter((r) => norm((r.fields || {}).Email) === c.email) : [];
const how = byId.length ? 'Shopify Customer ID' : 'email';
const rank = (r) => [r.fields['Record Status'] === 'Duplicate' ? 1 : 0, r.fields['Shopify Customer ID'] ? 0 : 1, Date.parse(r.createdTime) || 0];
const pool = (byId.length ? byId : byEmail).slice().sort((a, b) => {
  const x = rank(a); const y = rank(b);
  for (let i = 0; i < x.length; i++) if (x[i] !== y[i]) return x[i] - y[i];
  return 0;
});

let chosen = pool[0] || null;
let survivorId = null;
if (chosen && chosen.fields['Record Status'] === 'Duplicate' && Array.isArray(chosen.fields['Merged Into']) && chosen.fields['Merged Into'][0]) {
  const target = chosen.fields['Merged Into'][0];
  const found = recs.find((r) => r.id === target);
  if (found) chosen = found; else survivorId = target;
}

ctx.customerWrite = null;
if (survivorId) {
  ctx.ids.customer = survivorId;
  memo.customer = memo.customer || { action: 'matched', name: c.name, how: `${how}, then Merged Into` };
} else if (chosen) {
  ctx.ids.customer = chosen.id;
  const f = chosen.fields;
  const updates = {};
  if (c.shopifyId && !f['Shopify Customer ID']) updates['Shopify Customer ID'] = c.shopifyId;
  if (c.name && !f.Name) updates.Name = c.name;
  if (c.phone && !f.Phone) updates.Phone = c.phone;
  // Ticked when an order says the buyer accepts marketing. Never unticked from an order.
  if (c.acceptsMarketing && !f['Accepts Marketing']) updates['Accepts Marketing'] = true;
  if (Object.keys(updates).length) {
    ctx.customerWrite = { kind: 'update', how, method: 'PATCH', body: { records: [{ id: chosen.id, fields: updates }] } };
  } else {
    memo.customer = memo.customer || { action: 'matched', name: f.Name || c.name, how };
  }
} else if (c.shopifyId || c.email) {
  const fields = { 'Created Via': 'Shopify', 'Record Status': 'Active', 'Accepts Marketing': c.acceptsMarketing };
  if (c.name) fields.Name = c.name;
  if (c.email) fields.Email = c.email;
  if (c.phone) fields.Phone = c.phone;
  if (c.shopifyId) fields['Shopify Customer ID'] = c.shopifyId;
  // With a Shopify Customer ID the create is an upsert on that id, so two webhooks for the same new
  // customer that arrive together end up on one record.
  ctx.customerWrite = c.shopifyId
    ? { kind: 'create', how: 'new', method: 'PATCH', body: { performUpsert: { fieldsToMergeOn: ['Shopify Customer ID'] }, records: [{ fields }] } }
    : { kind: 'create', how: 'new', method: 'POST', body: { records: [{ fields }] } };
} else {
  memo.customer = memo.customer || { action: 'none' };
}

ctx.hasCustomerWrite = Boolean(ctx.customerWrite);
if (ctx.hasCustomerWrite) {
  ctx.step = 'Save Customer';
  await new Promise((resolve) => setTimeout(resolve, 500)); // pace Airtable
}
return { json: ctx };

// The customer record id the order will link to, and what happened to the customer.
const ctx = { ...$('Code: Pick Customer').item.json };
const memo = ctx.memo;
const rec = (Array.isArray($json.records) ? $json.records : [])[0];
if (!rec || !rec.id) throw new Error('Airtable saved the customer but returned no record id');
ctx.ids.customer = rec.id;
const created = Array.isArray($json.createdRecords) ? $json.createdRecords.includes(rec.id) : ctx.customerWrite.kind === 'create';
memo.customer = memo.customer || {
  action: created ? 'created' : 'updated',
  name: (rec.fields || {}).Name || ctx.order.customer.name,
  how: ctx.customerWrite.how,
};
return { json: ctx };

// One lookup for every SKU on the order. SKUs are compared trimmed and in upper case on both sides,
// so " dc-bar-milk-caramel" from Shopify still finds DC-BAR-MILK-CARAMEL.
const ctx = { ...$json };
delete ctx.customerWrite;
const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
const skus = [...new Set(ctx.order.lines.map((l) => l.sku).filter(Boolean))];
ctx.q.products = skus.length ? `OR(${skus.map((s) => `UPPER(TRIM({SKU})) = '${esc(s)}'`).join(', ')})` : 'FALSE()';
ctx.step = 'Find Products';
await new Promise((resolve) => setTimeout(resolve, 500)); // pace Airtable
return { json: ctx };

// Links each SKU to its product. A SKU with no product is created as a Draft product with Needs Review
// ticked (an upsert on SKU, in batches of at most 10). An existing Draft, such as one created by an
// earlier order, is matched like any other product and never created again.
const ctx = { ...$('Code: Plan Product Lookup').item.json };
const memo = ctx.memo;
const o = ctx.order;
const recs = Array.isArray($json.records) ? $json.records : [];
const RANK = { Active: 0, Draft: 1, Discontinued: 2 };
const bySku = {};
for (const r of recs) {
  const k = String((r.fields || {}).SKU || '').trim().toUpperCase();
  if (k) (bySku[k] = bySku[k] || []).push(r);
}
ctx.ids.products = {};
for (const [k, list] of Object.entries(bySku)) {
  list.sort((a, b) => ((RANK[a.fields.Status] ?? 3) - (RANK[b.fields.Status] ?? 3)) || (Date.parse(a.createdTime) - Date.parse(b.createdTime)));
  ctx.ids.products[k] = list[0].id;
}

const records = [];
const seen = new Set();
for (const l of o.lines) {
  if (!l.sku || ctx.ids.products[l.sku] || seen.has(l.sku)) continue;
  seen.add(l.sku);
  records.push({ fields: {
    SKU: l.sku,
    Name: l.title || l.sku,
    Status: 'Draft',
    'Needs Review': true,
    'Review Reason': `Created automatically from Shopify order ${o.number}: unknown SKU${l.variantId ? ` (Shopify variant ${l.variantId})` : ''}. Add allergens, ingredients and stock rules before selling.`,
    Price: l.unit,
  } });
}
ctx.draftBatches = [];
for (let i = 0; i < records.length; i += 10) ctx.draftBatches.push(records.slice(i, i + 10));
ctx.draftIndex = 0;
ctx.hasDrafts = ctx.draftBatches.length > 0;
memo.draftSkus = memo.draftSkus || [];
return { json: ctx };

// One Airtable request per pass, at most 10 records, 500 ms apart.
const ctx = { ...$json };
ctx.records = ctx.draftBatches[ctx.draftIndex];
ctx.step = `Create Draft Products (batch ${ctx.draftIndex + 1} of ${ctx.draftBatches.length})`;
await new Promise((resolve) => setTimeout(resolve, 500)); // pace Airtable
return { json: ctx };

// Remembers the new product ids, and which SKUs this webhook created (for the SKU alert and the order flag).
const ctx = { ...$('Code: Next Draft Batch').item.json };
const memo = ctx.memo;
const created = new Set(Array.isArray($json.createdRecords) ? $json.createdRecords : []);
for (const r of Array.isArray($json.records) ? $json.records : []) {
  const k = String((r.fields || {}).SKU || '').trim().toUpperCase();
  ctx.ids.products[k] = r.id;
  if (created.has(r.id) && !memo.draftSkus.includes(k)) memo.draftSkus.push(k);
}
delete ctx.records;
ctx.draftIndex += 1;
ctx.moreDrafts = ctx.draftIndex < ctx.draftBatches.length;
return { json: ctx };

// Open-Meteo geocoding answers 200 even when nothing matches (no results, or an empty list).
// A place it cannot find means Cold Pack Review: a person checks the forecast instead of guessing.
const ctx = { ...$('IF: Melt Check Needed?').item.json };
const results = Array.isArray($json.results) ? $json.results : [];
const r = results[0];
const lat = r ? Number(r.latitude) : NaN;
const lon = r ? Number(r.longitude) : NaN;
if (Number.isFinite(lat) && Number.isFinite(lon)) {
  ctx.cityFound = true;
  ctx.place = { name: r.name || ctx.order.ship.city, admin1: r.admin1 || '', country: r.country_code || '', latitude: lat, longitude: lon };
  ctx.forecastQuery = { latitude: lat, longitude: lon, daily: 'temperature_2m_max', timezone: 'auto', forecast_days: ctx.meltConfig.days };
} else {
  ctx.cityFound = false;
  ctx.memo.melt = {
    coldPack: 'Review', max: null, checked: true, checkedAt: new Date().toISOString(), failed: 'place not found',
    note: `Melt check could not run: Open-Meteo geocoding found no place called "${ctx.geo.query.name}"${ctx.geo.query.countryCode ? ` in ${ctx.geo.query.countryCode}` : ''}. Cold Pack set to Review, check the forecast for ${ctx.geo.label} by hand.`,
  };
}
return { json: ctx };

// Cold Pack is Required when any of the first MELT_FORECAST_DAYS daily maximums (day 1 is today at the
// destination) reaches MELT_TEMP_C. Missing or broken forecast data means Review, never a guess.
const ctx = { ...$('Code: Read Location').item.json };
const { limit, days } = ctx.meltConfig;
const daily = $json.daily || {};
const raw = Array.isArray(daily.temperature_2m_max) ? daily.temperature_2m_max.slice(0, days) : [];
const temps = raw.map((t) => (t === null || t === undefined || t === '' ? NaN : Number(t)));
const place = [ctx.place.name, ctx.place.admin1].filter(Boolean).join(', ');
const checkedAt = new Date().toISOString();
if (temps.length < days || temps.some((t) => !Number.isFinite(t))) {
  ctx.memo.melt = {
    coldPack: 'Review', max: null, checked: true, checkedAt, failed: 'incomplete forecast',
    note: `Melt check could not finish: the Open-Meteo forecast for ${place} did not include ${days} days of maximum temperatures. Cold Pack set to Review, check the forecast by hand.`,
  };
} else {
  const max = Math.round(Math.max(...temps) * 10) / 10;
  const hot = temps.some((t) => t >= limit);
  ctx.memo.melt = {
    coldPack: hot ? 'Required' : 'Not Needed', max, checked: true, checkedAt, place,
    note: `Forecast max ${max.toFixed(1)} C over the next ${days} days in ${place} (cold pack from ${limit} C).`,
  };
}
return { json: ctx };

// The geocoding or forecast call failed after 3 tries. The order is still saved, with Cold Pack Review
// and a note that says why, and the packing team gets a "check by hand" message.
const ctx = { ...$json };
const err = ctx.error || {};
delete ctx.error;
const status = Number(err.status || err.statusCode || (err.response && err.response.status)) || null;
const service = ctx.cityFound === true ? 'forecast' : 'geocoding';
ctx.memo.melt = {
  coldPack: 'Review', max: null, checked: true, checkedAt: new Date().toISOString(), failed: `${service} ${status || 'no answer'}`,
  note: `Melt check failed: the Open-Meteo ${service} service ${status ? `answered HTTP ${status}` : 'did not answer'} after 3 tries. Cold Pack set to Review, check the forecast for ${ctx.geo.label} by hand.`,
};
return { json: ctx };

// The Orders record for an upsert on Shopify Order ID. Every webhook carries the whole order, so the
// same upsert serves orders/create and orders/updated. Fields a person may have set (Needs Review,
// a linked product, a typed gift note) are only ever added to, never cleared.
const ctx = { ...$json };
const memo = ctx.memo;
const o = ctx.order;
const f = {
  'Order Number': o.number,
  'Shopify Order ID': o.shopifyId,
  'Shopify Updated At': o.updatedAt,
  'Order Status': o.status,
  'Cancelled At': o.cancelledAt,
  Subtotal: o.subtotal,
  Shipping: o.shipping,
  Tax: o.tax,
  Total: o.total,
  'Refunded Amount': o.refunded,
  Currency: o.currency,
  'Shopify Tags': o.tags,
  'Is Gift': o.isGift,
};
if (o.createdAt) f['Order Date'] = o.createdAt;
if (o.email) f.Email = o.email;
if (o.financial) f['Financial Status'] = o.financial;
if (o.fulfillment) f['Fulfillment Status'] = o.fulfillment;
if (o.giftNote) f['Gift Note'] = o.giftNote;
if (ctx.ids.customer) f.Customer = [ctx.ids.customer];
if (o.ship) {
  f['Shipping Name'] = o.ship.name;
  f['Shipping Address'] = o.ship.address;
  f['Shipping City'] = o.ship.city;
  f['Shipping Region'] = o.ship.region;
  f['Shipping Country'] = o.ship.country;
  f['Shipping Postal Code'] = o.ship.zip;
}
const melt = memo.melt;
if (melt) {
  if (melt.coldPack) f['Cold Pack'] = melt.coldPack;
  if (melt.checked) {
    f['Forecast Max C'] = melt.max;
    f['Melt Checked At'] = melt.checkedAt;
  }
  f['Melt Check Note'] = melt.note;
}

const reasons = [];
for (const l of o.lines) {
  if (l.sku && memo.draftSkus.includes(l.sku)) reasons.push(`Unknown SKU ${l.sku} on line ${l.position}. A draft product was created.`);
}
if (!ctx.ids.customer) reasons.push('No customer email or Shopify customer id on the order, so no customer is linked.');
if (o.financialRaw && !o.financial) reasons.push(`Unknown Shopify financial status "${o.financialRaw}".`);
if (o.fulfillmentRaw && !o.fulfillment) reasons.push(`Unknown Shopify fulfillment status "${o.fulfillmentRaw}".`);
const stored = (memo.before && memo.before.reviewReason) || '';
const fresh = reasons.filter((r) => !stored.includes(r));
if (fresh.length) {
  f['Needs Review'] = true;
  f['Review Reason'] = [stored, ...fresh].filter(Boolean).join('\n');
}
ctx.records = [{ fields: f }];
ctx.step = 'Upsert Order';
await new Promise((resolve) => setTimeout(resolve, 500)); // pace Airtable
return { json: ctx };

// The order is saved. Alerts go out now, before the lines, so a later failure cannot swallow them.
// Packing alert: when the melt check moves the order to Required or Review (or from Required to Not Needed).
// SKU alert: when this webhook created Draft products. memo makes sure neither is sent twice.
const ctx = { ...$('Code: Build Order').item.json };
delete ctx.records;
const memo = ctx.memo;
const o = ctx.order;
const rec = (Array.isArray($json.records) ? $json.records : [])[0];
if (!rec || !rec.id) throw new Error('Airtable saved the order but returned no record id');
ctx.ids.order = rec.id;
memo.orderAction = memo.orderAction || ((Array.isArray($json.createdRecords) && $json.createdRecords.includes(rec.id)) ? 'created' : 'updated');

// Slack reads &, < and > as control characters (<!channel>, <url|text>). Gift notes, names, addresses and
// product titles come from the shop and its customers, so they are escaped the way Slack documents.
const s = (v) => String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const handle = String($env.SHOPIFY_STORE_DOMAIN || '').trim().replace(/\.myshopify\.com$/i, '');
const link = /^[a-z0-9][a-z0-9-]*$/i.test(handle) && /^\d+$/.test(o.shopifyId)
  ? `<https://admin.shopify.com/store/${handle}/orders/${o.shopifyId}|${s(o.number)}>` : s(o.number);
const items = o.lines.filter((l) => l.current > 0).map((l) => `${l.current} x ${s(l.title || l.sku || 'item')}`).join(', ');
const shipTo = o.ship ? s([o.ship.name, o.ship.city, o.ship.region, o.ship.zip].filter(Boolean).join(', ')) : 'no shipping address';
const gift = o.isGift && o.giftNote ? `\nGift note for the packing slip: "${s(o.giftNote)}"` : (o.isGift ? '\nGift order (no message).' : '');

const melt = memo.melt;
const before = memo.before;
let packing = null;
if (melt && melt.checked && !memo.packingSent) {
  const was = before ? before.coldPack : null;
  const note = s(melt.note);
  if (melt.coldPack === 'Required' && was !== 'Required') {
    packing = `:snowflake: *Cold pack needed* for order ${link}\n${note}\nShip to: ${shipTo}\nItems: ${items}${gift}`;
  } else if (melt.coldPack === 'Review' && was !== 'Review') {
    packing = `:warning: *Check the cold pack by hand* for order ${link}\n${note}\nShip to: ${shipTo}\nItems: ${items}${gift}`;
  } else if (melt.coldPack === 'Not Needed' && was === 'Required') {
    packing = `*Cold pack no longer needed* for order ${link} (the shipping address changed)\n${note}\nShip to: ${shipTo}`;
  }
}
const packingUrl = String($env.SLACK_PACKING_WEBHOOK_URL || $env.SLACK_WEBHOOK_URL || '').trim();
const opsUrl = String($env.SLACK_WEBHOOK_URL || '').trim();

let sku = null;
if (memo.draftSkus.length && !memo.skuAlertSent) {
  const list = memo.draftSkus.map((code) => {
    const l = o.lines.find((x) => x.sku === code);
    return l && l.title ? `${s(code)} (${s(l.title)})` : s(code);
  }).join(', ');
  const one = memo.draftSkus.length === 1;
  sku = `:package: *New SKU from Shopify* on order ${link}\n${list} ${one ? 'is' : 'are'} not in Airtable, so ${one ? 'a Draft product was' : 'Draft products were'} created with Needs Review ticked. Add allergens, ingredients and stock rules, then set ${one ? 'it' : 'them'} to Active.`;
}

ctx.alerts = {
  packing: packing && packingUrl ? { url: packingUrl, text: packing } : null,
  sku: sku && opsUrl ? { url: opsUrl, text: sku } : null,
};
if (packing && !packingUrl) memo.packingSkipped = 'no Slack webhook URL is set';
if (sku && !opsUrl) memo.skuSkipped = 'no Slack webhook URL is set';
ctx.hasPackingAlert = Boolean(ctx.alerts.packing);
ctx.hasSkuAlert = Boolean(ctx.alerts.sku);
return { json: ctx };

// Runs whether the packing alert was sent, failed after 3 tries, or was not needed.
// A failed alert does not stop the order sync; the run is marked failed at the very end instead.
const ctx = { ...$('Code: Plan Alerts').item.json };
if (ctx.alerts.packing) {
  if ($json.error) {
    const e = $json.error;
    const status = Number(e.status || e.statusCode || (e.response && e.response.status)) || null;
    ctx.memo.packingError = `Slack answered ${status ? `HTTP ${status}` : 'nothing'} after 3 tries`;
  } else {
    ctx.memo.packingSent = true;
    delete ctx.memo.packingError;
  }
}
return { json: ctx };

// Same as the packing alert: record what happened, keep going.
const ctx = { ...$('Code: Note Packing Alert').item.json };
if (ctx.alerts.sku) {
  if ($json.error) {
    const e = $json.error;
    const status = Number(e.status || e.statusCode || (e.response && e.response.status)) || null;
    ctx.memo.skuError = `Slack answered ${status ? `HTTP ${status}` : 'nothing'} after 3 tries`;
  } else {
    ctx.memo.skuAlertSent = true;
    delete ctx.memo.skuError;
  }
}
return { json: ctx };

// One Order Lines record per Shopify line item, upserted on Line Item ID, so a rerun or an
// orders/updated webhook updates the same rows (quantities after refunds) instead of adding new ones.
// SKU Status: Matched (linked to a product, a new Draft included), Missing SKU (no SKU on the line),
// Unknown SKU (a SKU that could not be linked). The order itself carries the unknown SKU flag.
const ctx = { ...$json };
const o = ctx.order;
const records = o.lines.map((l) => {
  const fields = {
    'Line Item ID': l.id,
    Order: [ctx.ids.order],
    'Product Title': l.title,
    Quantity: l.quantity,
    'Current Quantity': l.current,
    'Refunded Quantity': l.refunded,
    'Unit Price': l.unit,
    'Line Total': l.total,
  };
  if (l.skuRaw.trim()) fields.SKU = l.skuRaw;
  const productId = l.sku ? ctx.ids.products[l.sku] : null;
  if (productId) fields.Product = [productId];
  fields['SKU Status'] = !l.sku ? 'Missing SKU' : (productId ? 'Matched' : 'Unknown SKU');
  return { fields };
});
ctx.lineBatches = [];
for (let i = 0; i < records.length; i += 10) ctx.lineBatches.push(records.slice(i, i + 10));
ctx.lineIndex = 0;
return { json: ctx };

// One Airtable request per pass, at most 10 records, 500 ms apart. One item per pass also keeps
// n8n's retry from sending earlier batches again.
const ctx = { ...$json };
ctx.records = ctx.lineBatches[ctx.lineIndex];
ctx.step = `Upsert Order Lines (batch ${ctx.lineIndex + 1} of ${ctx.lineBatches.length})`;
await new Promise((resolve) => setTimeout(resolve, 500)); // pace Airtable
return { json: ctx };

// Counts what the batch created and updated, then moves on to the next batch.
const ctx = { ...$('Code: Next Line Batch').item.json };
ctx.counts.linesCreated += Array.isArray($json.createdRecords) ? $json.createdRecords.length : 0;
ctx.counts.linesUpdated += Array.isArray($json.updatedRecords) ? $json.updatedRecords.length : 0;
delete ctx.records;
ctx.lineIndex += 1;
ctx.moreLines = ctx.lineIndex < ctx.lineBatches.length;
return { json: ctx };

// Writes the Webhook Log row last, as Processed (or Ignored for a stale webhook). Until this row exists a
// redelivery of the same webhook is processed again, which is safe because every write is an upsert.
const ctx = { ...$json };
delete ctx.records;
const memo = ctx.memo;
const o = ctx.order;
const parts = [];
const problems = [];
if (ctx.stale) {
  parts.push(`Skipped. This ${ctx.topic} webhook has updated_at ${o.updatedAt}, older than the version already in Airtable (${ctx.stored.updatedAt}).`);
  // A cooldown restart can find a newer version saved in the meantime. Say what the first attempt already did.
  const drafts = memo.draftSkus || [];
  if (drafts.length) parts.push(`Before that, this webhook created Draft products for ${drafts.join(', ')} (Needs Review is ticked on them).`);
  if (memo.customer && memo.customer.action === 'created') parts.push(`Before that, this webhook created the customer ${memo.customer.name || o.customer.email}.`);
} else {
  parts.push(`Order ${o.number} ${memo.orderAction || 'saved'}.`);
  const c = memo.customer || { action: 'none' };
  if (c.action === 'created') parts.push(`Customer created (${c.name || o.customer.email}).`);
  else if (c.action === 'updated') parts.push(`Customer updated (${c.name || o.customer.email}, matched by ${c.how}).`);
  else if (c.action === 'matched') parts.push(`Customer matched by ${c.how} (${c.name || o.customer.email}).`);
  else parts.push('No customer linked.');
  const n = o.lines.length;
  parts.push(`${n} line${n === 1 ? '' : 's'} (${ctx.counts.linesCreated} new, ${ctx.counts.linesUpdated} updated).`);
  if (memo.draftSkus.length) parts.push(`Draft product created for ${memo.draftSkus.join(', ')}.`);
  if (memo.melt && memo.melt.checked) parts.push(`Cold Pack ${memo.melt.coldPack}. ${memo.melt.note}`);
  else if (memo.melt) parts.push(memo.melt.note);
  else if (memo.before && memo.before.coldPack) parts.push(`Melt check not repeated, Cold Pack stays ${memo.before.coldPack}.`);
  if (memo.packingSent) parts.push('Packing alert sent.');
  if (memo.skuAlertSent) parts.push('New SKU alert sent.');
  if (memo.melt && memo.melt.failed) problems.push(`Weather check problem (${memo.melt.failed}).`);
  if (memo.packingError) problems.push(`Packing alert not sent, ${memo.packingError}.`);
  if (memo.skuError) problems.push(`New SKU alert not sent, ${memo.skuError}.`);
  if (memo.packingSkipped) parts.push(`Packing alert skipped, ${memo.packingSkipped}.`);
  if (memo.skuSkipped) parts.push(`New SKU alert skipped, ${memo.skuSkipped}.`);
}
ctx.summary = parts.join(' ');
ctx.problems = problems;
const orderId = ctx.ids.order || (ctx.stored && ctx.stored.id) || (memo.before && memo.before.id) || null;
const fields = {
  'Event ID': ctx.webhookId,
  Source: 'Shopify',
  Topic: ctx.topic,
  'Received At': ctx.receivedAt,
  Status: ctx.stale ? 'Ignored' : 'Processed',
  Notes: [ctx.summary, ...problems].join(' '),
};
if (orderId) fields.Order = [orderId];
ctx.records = [{ fields }];
ctx.step = 'Log Webhook';
await new Promise((resolve) => setTimeout(resolve, 500)); // pace Airtable
return { json: ctx };

// One Sync Log row per webhook (upsert on Run ID, so a cooldown restart updates the same row).
const ctx = { ...$('Code: Build Logs').item.json };
const memo = ctx.memo;
const o = ctx.order;
memo.webhookLogged = true;
const c = memo.customer || {};
const changed = ctx.stale ? 0
  : (['created', 'updated'].includes(c.action) ? 1 : 0) + memo.draftSkus.length + 1 + ctx.counts.linesCreated + ctx.counts.linesUpdated;
const fields = {
  'Run ID': `orders-${ctx.webhookId}`,
  Automation: '01 Shopify Orders',
  Trigger: 'Webhook',
  'Started At': ctx.startedAt,
  'Finished At': new Date().toISOString(),
  Status: ctx.problems.length ? 'Partial' : 'Success',
  'Items Checked': ctx.stale ? 0 : o.lines.length,
  'Items Changed': changed,
  'Shopify Updates': 0,
  Errors: ctx.problems.length,
  Details: [`${ctx.topic} ${o.number}.`, ctx.summary, ...ctx.problems].join(' '),
};
ctx.records = [{ fields }];
const failed = [];
if (memo.packingError) failed.push(`the packing alert (${memo.packingError})`);
if (memo.skuError) failed.push(`the new SKU alert (${memo.skuError})`);
ctx.alertFailed = failed.length > 0;
ctx.alertFailureText = ctx.alertFailed
  ? `Order ${o.number} is saved in Airtable, but ${failed.join(' and ')} could not be posted to Slack.${memo.melt && memo.melt.coldPack ? ` Cold Pack is ${memo.melt.coldPack}.` : ''} Tell the packing team by hand.`
  : '';
ctx.step = 'Log Run';
await new Promise((resolve) => setTimeout(resolve, 500)); // pace Airtable
return { json: ctx };

// Every Airtable node sends its error output here (after n8n's own 3 tries).
// 429 (rate limit), 5xx and no answer: wait 31 to 60 seconds (Airtable blocks a base for 30 seconds after a
// burst; the random part keeps runs that were blocked together from coming back together) and start the
// webhook again from the top. Every lookup and upsert is safe to repeat, and ctx.memo keeps the decisions and
// the alerts already sent. Anything else, or a third failure: log it and stop the run.
const ctx = { ...$json };
const err = ctx.error || {};
delete ctx.error;
const o = ctx.order;
const status = Number(err.status || err.statusCode || (err.response && err.response.status)) || null;
let type = '';
let detail = '';
try {
  const m = String(err.message || '');
  const body = JSON.parse(JSON.parse(m.slice(m.indexOf(' - ') + 3)));
  const e = body && body.error;
  type = typeof e === 'string' ? e : (e && e.type) || '';
  detail = (e && typeof e === 'object' && e.message) || '';
} catch (x) { /* not an Airtable JSON error body */ }
if (!type) type = status === 429 ? 'RATE_LIMIT_REACHED' : (err.code || (status ? 'HTTP_ERROR' : 'NO_RESPONSE'));
// The webhook id comes from a header (not signed), and this text is posted to Slack by the error workflow.
const shownId = String(ctx.webhookId || '').replace(/[^A-Za-z0-9._\/@-]/g, '?').slice(0, 64);
const MAX_ATTEMPTS = 3;
const transient = status === 429 || status === null || status >= 500;
ctx.retry = transient && ctx.attempt < MAX_ATTEMPTS;
if (ctx.retry) ctx.cooldownSeconds = 31 + Math.floor(Math.random() * 30);
const clean = (s) => String(s || '').replace(/https?:\/\/\S+/g, '').replace(/: /g, ', ').replace(/\s+/g, ' ').trim();
const what = `Airtable answered ${status || 'nothing'} ${type}${detail ? ` (${clean(detail)})` : ''} at step ${ctx.step}`;
const tries = `${ctx.attempt} attempt${ctx.attempt === 1 ? '' : 's'}`;
const hint = ctx.memo.duplicateOrderRows && ctx.step === 'Upsert Order'
  ? ` Two Orders records have Shopify Order ID ${o.shopifyId}, merge them in Airtable.` : '';
const next = ctx.memo.webhookLogged
  ? `The order and its lines are saved and webhook ${shownId} is logged as Processed, only the Sync Log row is missing.`
  : `Webhook ${shownId} is not marked Processed, so the next orders/updated for this order (or a redelivery) writes it again.`;
ctx.failure = {
  status, type, step: ctx.step, attempt: ctx.attempt,
  text: `Order ${o.number} from ${ctx.topic} was not fully saved after ${tries}. ${what}.${hint} ${next}`,
};
if (!ctx.retry) {
  const fields = {
    'Event ID': ctx.webhookId,
    Source: 'Shopify',
    Topic: ctx.topic,
    'Received At': ctx.receivedAt,
    Status: ctx.memo.webhookLogged ? 'Processed' : 'Failed',
    Notes: ctx.failure.text,
  };
  if (ctx.ids && ctx.ids.order) fields.Order = [ctx.ids.order];
  ctx.records = [{ fields }];
  ctx.step = 'Log Failure';
  await new Promise((resolve) => setTimeout(resolve, 500)); // pace Airtable
}
return { json: ctx };
